with d as (select value r from jsonb_array_elements($q$[{"slug":"spaghetti-puttanesca","title":"Spaghetti Puttanesca","cuisine":"italian","meal_types":["dinner"],"diets":["pescatarian","no-dairy"],"difficulty":"easy","total_minutes":25,"recipe":{"id":"spaghetti-puttanesca","title":"Spaghetti Puttanesca","summary":"A punchy pantry pasta of tomatoes, olives, capers, anchovies and chilli, on the table in 25 minutes.","cuisine":"italian","diets":["pescatarian","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":10,"cookMinutes":15,"servings":4,"onePot":false,"ingredientGroups":[{"items":[{"item":"spaghetti","raw":"400g spaghetti","quantity":400,"unit":"g","ingredientId":"spaghetti"},{"item":"extra virgin olive oil","raw":"3 tbsp extra virgin olive oil","quantity":3,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"garlic","raw":"4 garlic cloves, thinly sliced","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"thinly sliced"},{"item":"anchovy","raw":"6 anchovy fillets, chopped","quantity":6,"unit":"fillet","ingredientId":"anchovy","prep":"chopped"},{"item":"chilli flakes","raw":"1/2 tsp chilli flakes","quantity":0.5,"unit":"tsp","ingredientId":"chilli-flakes"},{"item":"400g tins crushed tomatoes","raw":"2 x 400g tins crushed tomatoes","quantity":2,"ingredientId":"tinned-tomatoes"},{"item":"pitted kalamata olives","raw":"100g pitted kalamata olives, roughly chopped","quantity":100,"unit":"g","ingredientId":"kalamata-olive","prep":"roughly chopped"},{"item":"capers","raw":"2 tbsp capers, rinsed","quantity":2,"unit":"tbsp","ingredientId":"capers","prep":"rinsed"},{"item":"dried oregano","raw":"1/2 tsp dried oregano","quantity":0.5,"unit":"tsp","ingredientId":"dried-oregano"},{"item":"salt","raw":"1 tsp salt, plus more for the pasta water","quantity":1,"unit":"tsp","ingredientId":"salt","prep":"plus more for the pasta water"},{"item":"flat-leaf parsley","raw":"Small handful of flat-leaf parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped","note":"small handful"}]}],"steps":[{"text":"Bring a large saucepan of well-salted water to a rolling boil, until it is bubbling vigorously."},{"text":"Meanwhile, warm the oil in a large frying pan over medium-low heat. Add the garlic, anchovies and chilli flakes and cook for 2 to 3 minutes, stirring, until the anchovies melt into the oil and the garlic is pale gold."},{"text":"Add the tomatoes, olives, capers and oregano. Simmer for 10 to 12 minutes, stirring now and then, until thick. Taste and add salt only if needed."},{"text":"Cook the spaghetti until just al dente, about 1 minute less than the packet says. Scoop out a cup of the cooking water, then drain."},{"text":"Toss the spaghetti into the sauce with a splash of the pasta water and cook for 1 minute, until the sauce clings. Scatter with parsley and serve."}],"notes":["The anchovies dissolve and give depth rather than fishiness. For a vegetarian version leave them out and add another tablespoon of capers."],"source":"user","provenance":"ai-draft"}},{"slug":"zucchini-frittata","title":"Zucchini and Herb Frittata","cuisine":"italian","meal_types":["breakfast","lunch"],"diets":["no-gluten"],"difficulty":"easy","total_minutes":40,"recipe":{"id":"zucchini-frittata","title":"Zucchini and Herb Frittata","summary":"A thick, soft-set frittata of golden zucchini, parmesan, mint and basil, good warm or cold.","cuisine":"italian","diets":["no-gluten"],"mealTypes":["breakfast","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":25,"servings":4,"onePot":true,"seasons":["summer"],"ingredientGroups":[{"items":[{"item":"zucchini","raw":"3 zucchini (about 500g), grated","quantity":3,"ingredientId":"zucchini","prep":"grated","note":"about 500g"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"spring onions","raw":"4 spring onions, thinly sliced","quantity":4,"ingredientId":"spring-onion","prep":"thinly sliced"},{"item":"garlic","raw":"1 garlic clove, crushed","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"eggs","raw":"8 eggs","quantity":8,"ingredientId":"egg"},{"item":"parmesan","raw":"50g parmesan, finely grated","quantity":50,"unit":"g","ingredientId":"parmesan","prep":"finely grated"},{"item":"black pepper","raw":"1/4 tsp black pepper","quantity":0.25,"unit":"tsp","ingredientId":"black-pepper"},{"item":"mint leaves","raw":"Handful of mint leaves, chopped","quantity":1,"unit":"handful","ingredientId":"mint","prep":"chopped"},{"item":"basil leaves","raw":"Handful of basil leaves, torn","quantity":1,"unit":"handful","ingredientId":"basil","prep":"torn"},{"item":"butter","raw":"15g butter","quantity":15,"unit":"g","ingredientId":"butter"}]}],"steps":[{"text":"Toss the grated zucchini with half the salt in a colander and leave for 10 minutes. Squeeze out as much water as you can with your hands."},{"text":"Heat the oven grill to medium-high. Warm the oil in a 24cm ovenproof non-stick frying pan over medium heat. Cook the spring onion for 2 minutes, then add the zucchini and garlic and cook for 5 minutes, until dry and starting to colour."},{"text":"Whisk the eggs with the parmesan, the rest of the salt, pepper and most of the herbs."},{"text":"Add the butter to the pan, let it melt, then pour in the eggs. Cook over low heat for 10 to 12 minutes without stirring, until the edges are set and the top is still a little wet."},{"text":"Slide the pan under the grill for 3 to 4 minutes, until the top is set and lightly golden. Rest for 5 minutes, then slide onto a board, scatter with the rest of the herbs and cut into wedges."}],"notes":["Keeps covered in the fridge for 2 days and makes a good lunchbox slice.","For a vegetarian version, use a vegetarian hard cheese (made without animal rennet)."],"source":"user","provenance":"ai-draft"}},{"slug":"panzanella","title":"Panzanella","cuisine":"italian","meal_types":["lunch","dinner"],"diets":["vegetarian","vegan","no-dairy"],"difficulty":"easy","total_minutes":35,"recipe":{"id":"panzanella","title":"Panzanella","summary":"Tuscan bread salad of ripe tomatoes, cucumber and toasted sourdough soaking up a sharp red wine vinegar dressing.","cuisine":"italian","diets":["vegetarian","vegan","no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":25,"cookMinutes":10,"servings":4,"onePot":false,"seasons":["summer"],"ingredientGroups":[{"title":"Salad","items":[{"item":"day-old sourdough","raw":"300g day-old sourdough, torn into 3cm pieces","quantity":300,"unit":"g","ingredientId":"sourdough","prep":"torn into 3cm pieces"},{"item":"extra virgin olive oil","raw":"2 tbsp extra virgin olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"ripe tomatoes","raw":"800g ripe tomatoes, cut into chunks","quantity":800,"unit":"g","ingredientId":"tomato","prep":"cut into chunks"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"Lebanese cucumbers","raw":"2 Lebanese cucumbers, halved and sliced","quantity":2,"ingredientId":"cucumber","prep":"halved and sliced"},{"item":"red onion","raw":"1/2 red onion, very thinly sliced","quantity":0.5,"ingredientId":"red-onion","prep":"very thinly sliced"},{"item":"capers","raw":"1 tbsp capers, rinsed","quantity":1,"unit":"tbsp","ingredientId":"capers","prep":"rinsed"},{"item":"basil leaves","raw":"Large handful of basil leaves","quantity":1,"unit":"handful","ingredientId":"basil","note":"large handful"}]},{"title":"Dressing","items":[{"item":"extra virgin olive oil","raw":"4 tbsp extra virgin olive oil","quantity":4,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"red wine vinegar","raw":"2 tbsp red wine vinegar","quantity":2,"unit":"tbsp","ingredientId":"red-wine-vinegar"},{"item":"garlic","raw":"1 garlic clove, crushed","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"black pepper","raw":"1/4 tsp black pepper","quantity":0.25,"unit":"tsp","ingredientId":"black-pepper"}]}],"steps":[{"text":"Heat the oven to 200°C (180°C fan-forced). Toss the bread with the oil on a tray and bake for 8 to 10 minutes, until crisp outside but still a little chewy in the middle."},{"text":"Put the tomatoes in a large bowl with the salt and leave for 10 minutes to release their juices."},{"text":"Whisk the dressing ingredients together and pour over the tomatoes. Add the cucumber, onion, capers and toasted bread and toss well."},{"text":"Leave for 10 to 15 minutes so the bread soaks up the juices, then tear in the basil, toss again and serve."}],"notes":["It needs properly ripe, summer tomatoes. Out of season, use cherry tomatoes, halved."],"source":"user","provenance":"ai-draft"}},{"slug":"steak-au-poivre","title":"Steak au Poivre","cuisine":"french","meal_types":["dinner"],"diets":["no-gluten"],"difficulty":"medium","total_minutes":45,"recipe":{"id":"steak-au-poivre","title":"Steak au Poivre","summary":"Pepper-crusted sirloin seared hard and served with a brandy and cream pan sauce and crisp oven chips.","cuisine":"french","diets":["no-gluten"],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":15,"cookMinutes":30,"servings":2,"onePot":false,"ingredientGroups":[{"title":"Steak","items":[{"item":"sirloin steaks","raw":"2 sirloin steaks (about 250g each, 3cm thick)","quantity":2,"ingredientId":"beef-sirloin","note":"about 250g each, 3cm thick"},{"item":"black peppercorns","raw":"1 tbsp black peppercorns","quantity":1,"unit":"tbsp","ingredientId":"black-pepper"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"butter","raw":"15g butter","quantity":15,"unit":"g","ingredientId":"butter"}]},{"title":"Sauce","items":[{"item":"French shallot","raw":"1 French shallot, finely chopped","quantity":1,"ingredientId":"shallot","prep":"finely chopped"},{"item":"brandy","raw":"60ml brandy","quantity":60,"unit":"ml","ingredientId":"brandy"},{"item":"beef stock","raw":"125ml beef stock","quantity":125,"unit":"ml","ingredientId":"beef-stock"},{"item":"thickened cream","raw":"125ml thickened cream","quantity":125,"unit":"ml","ingredientId":"cream"}]},{"title":"To serve","items":[{"item":"frozen chips","raw":"500g frozen chips","quantity":500,"unit":"g","ingredientId":"frozen-chips"},{"item":"salad leaves","raw":"60g salad leaves","quantity":60,"unit":"g","ingredientId":"salad-leaves"}]}],"steps":[{"text":"Take the steaks out of the fridge 20 minutes before cooking. Heat the oven and cook the chips according to the packet."},{"text":"Crush the peppercorns coarsely in a mortar and pestle or under a heavy pan. Pat the steaks dry, season with salt and press the pepper firmly onto both sides."},{"text":"Heat the oil in a heavy frying pan over high heat until shimmering. Cook the steaks for 3 to 4 minutes a side for medium-rare, adding the butter for the last minute and spooning it over. Rest on a warm plate for 5 minutes."},{"text":"Pour off most of the fat and turn the heat to medium. Cook the shallot for 1 minute. Take the pan off the heat, add the brandy, then return it and let it bubble for 30 seconds (stand back, as it can flare). Add the stock and boil for 2 minutes until reduced by half."},{"text":"Stir in the cream and any resting juices and simmer for 2 minutes, until the sauce coats a spoon. Serve the steaks with the sauce poured over, chips and salad."}],"notes":["Never add brandy to a pan over a gas flame straight from the bottle; pour it into a cup first.","Check the label on your frozen chips if gluten matters: some are coated in wheat flour.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"source":"user","provenance":"ai-draft"}},{"slug":"moules-marinieres","title":"Moules Marinières","cuisine":"french","meal_types":["dinner"],"diets":["pescatarian"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"moules-marinieres","title":"Moules Marinières","summary":"Mussels steamed open in white wine, garlic and shallots, with a splash of cream and bread for the broth.","cuisine":"french","diets":["pescatarian"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":20,"cookMinutes":10,"servings":4,"onePot":true,"seasons":["autumn","winter","spring"],"ingredientGroups":[{"items":[{"item":"black mussels","raw":"2kg black mussels","quantity":2,"unit":"kg","ingredientId":"mussels"},{"item":"butter","raw":"40g butter","quantity":40,"unit":"g","ingredientId":"butter"},{"item":"French shallots","raw":"3 French shallots, finely chopped","quantity":3,"ingredientId":"shallot","prep":"finely chopped"},{"item":"garlic","raw":"3 garlic cloves, finely chopped","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"thyme","raw":"2 thyme sprigs","quantity":2,"unit":"sprig","ingredientId":"thyme"},{"item":"bay","raw":"1 bay leaf","quantity":1,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"dry white wine","raw":"250ml dry white wine","quantity":250,"unit":"ml","ingredientId":"white-wine"},{"item":"thickened cream","raw":"100ml thickened cream","quantity":100,"unit":"ml","ingredientId":"cream"},{"item":"flat-leaf parsley","raw":"Large handful of flat-leaf parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped","note":"large handful"},{"item":"black pepper","raw":"1/4 tsp black pepper","quantity":0.25,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"To serve","items":[{"item":"crusty baguette","raw":"1 crusty baguette, sliced","quantity":1,"ingredientId":"baguette","prep":"sliced"}]}],"steps":[{"text":"Rinse the mussels in cold water and pull off the hairy beards. Tap any open mussels on the bench: throw away any that don't close, and any with cracked shells."},{"text":"Melt the butter in a large, wide saucepan with a lid over medium heat. Cook the shallots, garlic, thyme and bay leaf for 3 minutes until soft but not coloured."},{"text":"Turn the heat to high, add the wine and bring to a rolling boil. Tip in the mussels, cover and cook for 4 to 5 minutes, shaking the pan once or twice, until the shells have opened."},{"text":"Lift the mussels into warm bowls with a slotted spoon, discarding any that stay shut. Stir the cream, parsley and pepper into the broth and bring back to the boil until the broth is bubbling and slightly thickened."},{"text":"Pour the broth over the mussels and serve straight away with bread for dipping and a bowl for the shells."}],"notes":["Buy mussels on the day you cook them and keep them in the fridge in an open bag under a damp cloth, not in water.","Leave out the cream for a lighter, dairy-free broth (use olive oil instead of butter).","Food safety: Cook mussels, clams and pipis only if they are alive and tightly closed (or close when tapped), and discard any that stay shut after cooking."],"source":"user","provenance":"ai-draft"}},{"slug":"leek-potato-soup","title":"Leek and Potato Soup","cuisine":"french","meal_types":["lunch","dinner"],"diets":["vegetarian","no-gluten"],"difficulty":"easy","total_minutes":55,"recipe":{"id":"leek-potato-soup","title":"Leek and Potato Soup","summary":"A silky, gently buttery French soup of slow-softened leeks and potatoes, finished with cream and chives.","cuisine":"french","diets":["vegetarian","no-gluten"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":40,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"butter","raw":"40g butter","quantity":40,"unit":"g","ingredientId":"butter"},{"item":"leeks","raw":"3 leeks (white and pale green parts), sliced and washed","quantity":3,"ingredientId":"leek","prep":"sliced and washed","note":"white and pale green parts"},{"item":"brown onion","raw":"1 brown onion, chopped","quantity":1,"ingredientId":"brown-onion","prep":"chopped"},{"item":"garlic","raw":"2 garlic cloves, sliced","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"sliced"},{"item":"floury potatoes","raw":"600g floury potatoes, peeled and diced","quantity":600,"unit":"g","ingredientId":"potato","prep":"peeled and diced"},{"item":"vegetable stock","raw":"1.2L vegetable stock","quantity":1.2,"unit":"l","ingredientId":"vegetable-stock"},{"item":"bay","raw":"1 bay leaf","quantity":1,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"thyme","raw":"2 thyme sprigs","quantity":2,"unit":"sprig","ingredientId":"thyme"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"white pepper","raw":"1/4 tsp white pepper","quantity":0.25,"unit":"tsp","ingredientId":"white-pepper"},{"item":"thickened cream","raw":"100ml thickened cream","quantity":100,"unit":"ml","ingredientId":"cream"},{"item":"chives","raw":"2 tbsp chives, snipped","quantity":2,"unit":"tbsp","ingredientId":"chives","prep":"snipped"}]},{"title":"To serve","items":[{"item":"Crusty bread","raw":"Crusty bread, to serve (optional)","ingredientId":"crusty-bread","prep":"to serve","optional":true}]}],"steps":[{"text":"Melt the butter in a large saucepan over medium-low heat. Add the leeks, onion and garlic with a pinch of the salt, cover and cook for 15 minutes, stirring now and then, until very soft but not browned."},{"text":"Add the potatoes, stock, bay leaf and thyme. Bring to the boil, then simmer, partly covered, for 20 minutes until the potatoes are completely tender."},{"text":"Fish out the bay leaf and thyme stalks. Blend until smooth with a stick blender (or in batches in a blender, with the lid vented)."},{"text":"Stir in the cream, the rest of the salt and the white pepper and warm through without boiling. Serve scattered with chives, with bread on the side."}],"notes":["Leeks hide grit between their layers: slice them first, then swish in a big bowl of water and lift them out.","Chill it and serve cold in summer and it becomes vichyssoise."],"source":"user","provenance":"ai-draft"}},{"slug":"crepes-lemon-sugar","title":"Crêpes with Lemon and Sugar","cuisine":"french","meal_types":["breakfast","snack"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":55,"recipe":{"id":"crepes-lemon-sugar","title":"Crêpes with Lemon and Sugar","summary":"Thin, lacy French pancakes rolled with a squeeze of lemon and a sprinkle of caster sugar.","cuisine":"french","diets":["vegetarian"],"mealTypes":["breakfast","snack"],"difficulty":"easy","prepMinutes":35,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Batter","items":[{"item":"plain flour","raw":"150g plain flour","quantity":150,"unit":"g","ingredientId":"plain-flour"},{"item":"salt","raw":"1/4 tsp salt","quantity":0.25,"unit":"tsp","ingredientId":"salt"},{"item":"caster sugar","raw":"1 tbsp caster sugar","quantity":1,"unit":"tbsp","ingredientId":"caster-sugar"},{"item":"eggs","raw":"3 eggs","quantity":3,"ingredientId":"egg"},{"item":"milk","raw":"375ml milk","quantity":375,"unit":"ml","ingredientId":"milk"},{"item":"butter","raw":"30g butter, melted, plus extra for the pan","quantity":30,"unit":"g","ingredientId":"butter","prep":"melted, plus extra for the pan"}]},{"title":"To serve","items":[{"item":"lemons","raw":"2 lemons, cut into wedges","quantity":2,"ingredientId":"lemon","prep":"cut into wedges"},{"item":"caster sugar","raw":"4 tbsp caster sugar","quantity":4,"unit":"tbsp","ingredientId":"caster-sugar"}]}],"steps":[{"text":"Whisk the flour, salt and sugar in a bowl. Make a well, add the eggs and a splash of the milk and whisk to a thick, smooth paste. Gradually whisk in the rest of the milk, then the melted butter. The batter should be the consistency of pouring cream."},{"text":"Rest the batter for 30 minutes at room temperature (or up to a day in the fridge)."},{"text":"Heat a 22 to 24cm non-stick frying pan over medium heat and wipe it with a little butter. Pour in about 3 tbsp of batter and swirl quickly to coat the base thinly."},{"text":"Cook for about 1 minute, until the edges lift and the underside is golden, then flip and cook for 30 seconds more. Stack the crêpes on a plate under a tea towel while you cook the rest. The first one is usually a tester."},{"text":"To serve, squeeze lemon over each crêpe, sprinkle with sugar, and fold into quarters or roll up."}],"notes":["Makes about 12. Leftover crêpes keep in the fridge, layered with baking paper, for 2 days."],"source":"user","provenance":"ai-draft"}},{"slug":"patatas-bravas","title":"Patatas Bravas","cuisine":"spanish","meal_types":["snack","dinner"],"diets":["vegetarian","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":60,"recipe":{"id":"patatas-bravas","title":"Patatas Bravas","summary":"Crisp oven-roasted potatoes with a smoky, spicy tomato sauce and a drizzle of garlicky aioli.","cuisine":"spanish","diets":["vegetarian","no-gluten","no-dairy"],"mealTypes":["snack","dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":45,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Potatoes","items":[{"item":"potatoes","raw":"1kg potatoes, cut into 3cm chunks","quantity":1,"unit":"kg","ingredientId":"potato","prep":"cut into 3cm chunks"},{"item":"olive oil","raw":"4 tbsp olive oil","quantity":4,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"}]},{"title":"Bravas sauce","items":[{"item":"olive oil","raw":"1 tbsp olive oil","quantity":1,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"brown onion","raw":"1/2 brown onion, finely chopped","quantity":0.5,"ingredientId":"brown-onion","prep":"finely chopped"},{"item":"garlic","raw":"2 garlic cloves, crushed","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"smoked paprika","raw":"2 tsp smoked paprika","quantity":2,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"cayenne pepper","raw":"1/2 tsp cayenne pepper","quantity":0.5,"unit":"tsp","ingredientId":"cayenne"},{"item":"passata","raw":"250ml passata","quantity":250,"unit":"ml","ingredientId":"passata"},{"item":"sherry vinegar","raw":"1 tsp sherry vinegar","quantity":1,"unit":"tsp","ingredientId":"sherry-vinegar"},{"item":"white sugar","raw":"1/2 tsp white sugar","quantity":0.5,"unit":"tsp","ingredientId":"sugar"},{"item":"salt","raw":"1/4 tsp salt","quantity":0.25,"unit":"tsp","ingredientId":"salt"}]},{"title":"To serve","items":[{"item":"aioli","raw":"100g aioli","quantity":100,"unit":"g","ingredientId":"aioli"},{"item":"flat-leaf parsley","raw":"1 tbsp flat-leaf parsley, chopped","quantity":1,"unit":"tbsp","ingredientId":"parsley","prep":"chopped"}]}],"steps":[{"text":"Heat the oven to 220°C (200°C fan-forced). Put the potatoes in a saucepan of cold salted water, bring to the boil and simmer for 5 minutes. Drain well and leave to steam dry for 5 minutes, then shake in the pan to rough up the edges."},{"text":"Toss the potatoes with the oil and salt on a large tray in a single layer. Roast for 35 to 40 minutes, turning once, until deep golden and crisp."},{"text":"Meanwhile, make the sauce: warm the oil in a small saucepan over medium heat and cook the onion for 5 minutes until soft. Add the garlic, smoked paprika and cayenne and stir for 30 seconds."},{"text":"Add the passata, vinegar, sugar and salt and simmer for 10 minutes until thick. Blend smooth if you like."},{"text":"Pile the potatoes on a plate, spoon over the bravas sauce, drizzle with aioli and scatter with parsley. Serve hot."}],"notes":["Shop-bought aioli is fine here. Homemade aioli is made with raw egg, which isn't recommended for pregnant people, young children, older people or anyone with a weakened immune system.","Halve the cayenne for a milder sauce."],"source":"user","provenance":"ai-draft"}},{"slug":"pan-con-tomate","title":"Pan con Tomate","cuisine":"spanish","meal_types":["breakfast","snack"],"diets":["vegetarian","vegan","no-dairy"],"difficulty":"easy","total_minutes":15,"recipe":{"id":"pan-con-tomate","title":"Pan con Tomate","summary":"Catalan toast rubbed with garlic, topped with grated ripe tomato, good olive oil and flaky salt.","cuisine":"spanish","diets":["vegetarian","vegan","no-dairy"],"mealTypes":["breakfast","snack"],"difficulty":"easy","prepMinutes":10,"cookMinutes":5,"servings":4,"onePot":false,"seasons":["summer"],"ingredientGroups":[{"items":[{"item":"ripe tomatoes","raw":"4 ripe tomatoes","quantity":4,"ingredientId":"tomato"},{"item":"flaky sea salt","raw":"1/2 tsp flaky sea salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"thick slices sourdough","raw":"8 thick slices sourdough","quantity":8,"ingredientId":"sourdough"},{"item":"garlic","raw":"1 garlic clove, halved","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"halved"},{"item":"extra virgin olive oil","raw":"4 tbsp extra virgin olive oil","quantity":4,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"jamón serrano","raw":"8 slices jamón serrano, optional","quantity":8,"unit":"slice","ingredientId":"prosciutto","optional":true}]}],"steps":[{"text":"Halve the tomatoes crossways and grate the cut sides on the coarse side of a box grater into a bowl, until only the skin is left in your hand. Throw away the skins and stir a pinch of the salt into the pulp."},{"text":"Toast or chargrill the bread until golden and crisp on both sides."},{"text":"While it's hot, rub one side of each slice lightly with the cut garlic."},{"text":"Spoon the tomato over the toast, which should be golden and crisp, drizzle generously with olive oil and finish with flaky salt. Top with jamón if you like, and eat straight away."}],"notes":["Without the jamón it's vegan."],"source":"user","provenance":"ai-draft"}},{"slug":"albondigas","title":"Albóndigas in Tomato Sauce","cuisine":"spanish","meal_types":["dinner"],"diets":[],"difficulty":"medium","total_minutes":65,"recipe":{"id":"albondigas","title":"Albóndigas in Tomato Sauce","summary":"Tender Spanish pork and beef meatballs simmered in a smoky paprika and white wine tomato sauce.","cuisine":"spanish","diets":[],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":25,"cookMinutes":40,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Meatballs","items":[{"item":"fresh breadcrumbs","raw":"40g fresh breadcrumbs","quantity":40,"unit":"g","ingredientId":"breadcrumbs"},{"item":"milk","raw":"3 tbsp milk","quantity":3,"unit":"tbsp","ingredientId":"milk"},{"item":"beef mince","raw":"300g beef mince","quantity":300,"unit":"g","ingredientId":"beef-mince"},{"item":"pork mince","raw":"300g pork mince","quantity":300,"unit":"g","ingredientId":"pork-mince"},{"item":"egg","raw":"1 egg","quantity":1,"ingredientId":"egg"},{"item":"garlic","raw":"2 garlic cloves, crushed","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"flat-leaf parsley","raw":"3 tbsp flat-leaf parsley, chopped","quantity":3,"unit":"tbsp","ingredientId":"parsley","prep":"chopped"},{"item":"smoked paprika","raw":"1 tsp smoked paprika","quantity":1,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/4 tsp black pepper","quantity":0.25,"unit":"tsp","ingredientId":"black-pepper"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"}]},{"title":"Sauce","items":[{"item":"brown onion","raw":"1 brown onion, finely chopped","quantity":1,"ingredientId":"brown-onion","prep":"finely chopped"},{"item":"garlic","raw":"2 garlic cloves, crushed","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"smoked paprika","raw":"1 tsp smoked paprika","quantity":1,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"dry white wine","raw":"125ml dry white wine","quantity":125,"unit":"ml","ingredientId":"white-wine"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"chicken stock","raw":"250ml chicken stock","quantity":250,"unit":"ml","ingredientId":"chicken-stock"},{"item":"bay","raw":"1 bay leaf","quantity":1,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"To serve","items":[{"item":"crusty baguette","raw":"1 crusty baguette, sliced","quantity":1,"ingredientId":"baguette","prep":"sliced"},{"item":"flat-leaf parsley","raw":"1 tbsp flat-leaf parsley, chopped","quantity":1,"unit":"tbsp","ingredientId":"parsley","prep":"chopped"}]}],"steps":[{"text":"Soak the breadcrumbs in the milk for 5 minutes. Add the beef, pork, egg, garlic, parsley, paprika, salt and pepper and mix with your hands until just combined. With wet hands, roll into walnut-sized balls (about 24)."},{"text":"Heat the oil in a large, deep frying pan over medium-high heat. Brown the meatballs in two batches for 5 minutes, turning, until coloured all over. They don't need to be cooked through yet. Set aside."},{"text":"Turn the heat to medium. Cook the onion in the same pan for 6 minutes until soft, then add the garlic and paprika for 30 seconds. Pour in the wine and let it bubble for 2 minutes."},{"text":"Add the tomatoes, stock, bay leaf and salt and bring to a simmer. Return the meatballs, cover and simmer gently for 20 minutes, until the sauce has thickened and the meatballs are cooked through (75°C in the centre)."},{"text":"Scatter with parsley and serve with bread for the sauce."}],"notes":["Serve as tapas with toothpicks, or with rice or chips as a main.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"avgolemono","title":"Avgolemono","cuisine":"greek","meal_types":["lunch","dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"medium","total_minutes":50,"recipe":{"id":"avgolemono","title":"Avgolemono","summary":"Greek chicken and rice soup turned silky and bright with a whisked egg and lemon finish.","cuisine":"greek","diets":["no-gluten","no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"medium","prepMinutes":10,"cookMinutes":40,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"chicken stock","raw":"1.75L chicken stock","quantity":1.75,"unit":"l","ingredientId":"chicken-stock"},{"item":"chicken thigh fillets","raw":"500g chicken thigh fillets","quantity":500,"unit":"g","ingredientId":"chicken-thigh"},{"item":"brown onion","raw":"1 brown onion, halved","quantity":1,"ingredientId":"brown-onion","prep":"halved"},{"item":"bay","raw":"1 bay leaf","quantity":1,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"medium-grain rice","raw":"150g medium-grain rice","quantity":150,"unit":"g","ingredientId":"white-rice"},{"item":"eggs","raw":"3 eggs","quantity":3,"ingredientId":"egg"},{"item":"lemons","raw":"Juice of 2 lemons","quantity":2,"ingredientId":"lemon","prep":"juiced"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/4 tsp black pepper","quantity":0.25,"unit":"tsp","ingredientId":"black-pepper"},{"item":"dill","raw":"2 tbsp dill, chopped","quantity":2,"unit":"tbsp","ingredientId":"dill","prep":"chopped"}]}],"steps":[{"text":"Put the stock, chicken, onion and bay leaf in a large saucepan and bring to a gentle simmer. Cook for 20 minutes, until the chicken is cooked through (75°C in the thickest part). Lift out the chicken, onion and bay leaf; throw away the onion and bay leaf."},{"text":"Add the rice to the simmering stock and cook for 15 minutes until tender. Shred the chicken with two forks while it cooks."},{"text":"Whisk the eggs in a heatproof bowl until frothy, then whisk in the lemon juice. Turn the soup down to the lowest heat. Ladle in about 250ml of the hot stock, a little at a time, whisking constantly, to warm the eggs without scrambling them."},{"text":"Pour the egg mixture back into the pan, stirring, then return the chicken. Keep the soup over low heat, stirring, for 3 to 4 minutes until it thickens slightly and is steaming. Don't let it boil, or the eggs will curdle."},{"text":"Season with salt, pepper and more lemon to taste, and serve scattered with dill."}],"notes":["Reheat leftovers gently over low heat, stirring, and never let it boil.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"briam","title":"Briam","cuisine":"greek","meal_types":["dinner","lunch"],"diets":["vegetarian","vegan","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":100,"recipe":{"id":"briam","title":"Briam","summary":"Greek tray-baked summer vegetables in tomato and plenty of olive oil, slow-roasted until sweet and jammy.","cuisine":"greek","diets":["vegetarian","vegan","no-gluten","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":25,"cookMinutes":75,"servings":4,"onePot":true,"seasons":["summer","autumn"],"ingredientGroups":[{"items":[{"item":"potatoes","raw":"600g potatoes, peeled and sliced 1cm thick","quantity":600,"unit":"g","ingredientId":"potato","prep":"peeled and sliced 1cm thick"},{"item":"zucchini","raw":"2 zucchini, cut into 1.5cm rounds","quantity":2,"ingredientId":"zucchini","prep":"cut into 1.5cm rounds"},{"item":"eggplant","raw":"1 eggplant, cut into 2cm chunks","quantity":1,"ingredientId":"eggplant","prep":"cut into 2cm chunks"},{"item":"red capsicum","raw":"1 red capsicum, cut into chunks","quantity":1,"ingredientId":"capsicum","prep":"cut into chunks"},{"item":"red onion","raw":"1 red onion, cut into thin wedges","quantity":1,"ingredientId":"red-onion","prep":"cut into thin wedges"},{"item":"garlic","raw":"4 garlic cloves, sliced","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"sliced"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"extra virgin olive oil","raw":"125ml extra virgin olive oil","quantity":125,"unit":"ml","ingredientId":"olive-oil"},{"item":"dried oregano","raw":"2 tsp dried oregano","quantity":2,"unit":"tsp","ingredientId":"dried-oregano"},{"item":"salt","raw":"1 1/2 tsp salt","quantity":1.5,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"water","raw":"125ml water","quantity":125,"unit":"ml","ingredientId":"water"},{"item":"flat-leaf parsley","raw":"Handful of flat-leaf parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped"}]},{"title":"To serve","items":[{"item":"feta","raw":"100g feta, crumbled (optional)","quantity":100,"unit":"g","ingredientId":"feta","prep":"crumbled","optional":true},{"item":"Crusty bread","raw":"Crusty bread, to serve (optional)","ingredientId":"crusty-bread","prep":"to serve","optional":true}]}],"steps":[{"text":"Heat the oven to 200°C (180°C fan-forced)."},{"text":"Put all the vegetables and garlic in a large roasting tin. Add the tomatoes, oil, oregano, salt, pepper and water and toss with your hands until everything is coated. Spread out evenly."},{"text":"Cover tightly with foil and bake for 40 minutes."},{"text":"Uncover, stir gently and bake for 30 to 35 minutes more, until the potatoes are tender and the vegetables are soft and caramelised at the edges."},{"text":"Rest for 10 minutes, scatter with parsley and serve warm, with feta and bread if you like."}],"notes":["It's even better the next day, at room temperature.","The bread and feta are what make it a meal; without them it's vegan and gluten free."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;